input.command:
python3 -c "
import json;d=json.load(open('fixtures/catalog.json'))
k=list(d['details'])[0]; x=d['details'][k]
print(list(x['catalog'].keys())); print(list(x['raw'].keys()))
import collections
geo=collections.Counter(); dests=collections.Counter()
for k,x in d['details'].items():
  for f in ('geohierarchy','geoHierarchy','destinations','destination'):
    for src in (x['catalog'],x['raw']):
      if f in src: 
        v=src[f]; 
        if f.lower()=='geohierarchy': geo[json.dumps(v,ensure_ascii=False)[:300]]+=1
        else: dests[json.dumps(v,ensure_ascii=False)[:200]]+=1
print(len(geo)); [print(c,g) for g,c in list(geo.items())[:6]]
print(len(dests)); [print(c,g) for g,c in list(dests.items())[:5]]
"

